// MWSOCCER2027: register purchased Premium Vault prospects in the career player database.
if (globalThis.FB && Array.isArray(globalThis.FB.players)) {
  globalThis.FB_syncVaultProspects = function(rt) {
    const vars = rt.getGame().getVariables();
    const clubVar = vars.get("ClubName");
    const currentClub = clubVar ? clubVar.getAsString() : "Thunder FC";
    const catalog = [
      {key:"AcademyProdigy10",name:"Academy Prodigy #10",nat:"Nigeria",pos:"FWD",ovr:88,pac:94,sho:87,pas:82,dri:90,def:42,phy:78},
      {key:"GoldenBootKid9",name:"Golden Boot Kid #9",nat:"Brazil",pos:"FWD",ovr:90,pac:96,sho:84,pas:88,dri:91,def:38,phy:82},
      {key:"WonderWing7",name:"Wonder Wing #7",nat:"England",pos:"FWD",ovr:89,pac:91,sho:86,pas:93,dri:95,def:45,phy:79},
      {key:"MidfieldMaestro8",name:"Midfield Maestro #8",nat:"Spain",pos:"MID",ovr:91,pac:82,sho:95,pas:96,dri:94,def:76,phy:84},
      {key:"DefensiveRock4",name:"Defensive Rock #4",nat:"France",pos:"DEF",ovr:87,pac:82,sho:70,pas:84,dri:78,def:96,phy:94},
      {key:"ElitePlaymaker10",name:"Elite Playmaker #10",nat:"Argentina",pos:"MID",ovr:93,pac:86,sho:91,pas:98,dri:97,def:68,phy:83},
      {key:"LightningStriker11",name:"Lightning Striker #11",nat:"Senegal",pos:"FWD",ovr:92,pac:98,sho:88,pas:82,dri:91,def:40,phy:93},
      {key:"WorldClassKeeper1",name:"World-Class Keeper #1",nat:"Germany",pos:"GK",ovr:94,pac:72,sho:55,pas:88,dri:78,def:92,phy:93},
      {key:"FutureCaptain6",name:"Future Captain #6",nat:"Japan",pos:"MID",ovr:92,pac:87,sho:90,pas:93,dri:91,def:84,phy:92},
      {key:"GlobalPhenomenon9",name:"Global Phenomenon #9",nat:"Portugal",pos:"FWD",ovr:96,pac:98,sho:94,pas:92,dri:97,def:55,phy:94}
    ];
    catalog.forEach((p) => {
      const flag = vars.get("Vault_"+p.key+"_Owned");
      if (!flag || !flag.getAsBoolean()) return;
      let existing = globalThis.FB.players.find(x => x.vaultKey === p.key);
      if (!existing) {
        const id = globalThis.FB.players.length;
        existing = Object.assign({}, p, {id:id, vaultKey:p.key, age:17, price:0, salary:Math.round(p.ovr*1800), contract:5, contractMonths:60, club:currentClub, owned:true, morale:95});
        globalThis.FB.players.push(existing);
      } else { existing.owned = true; if (!existing.club || existing.club === "Free Agents") existing.club = currentClub; }
    });
  };
  globalThis.FB_syncVaultProspects(rt);
}

