if(!globalThis.FB_renderContracts){
 globalThis.FB_renderContracts=function(rt){
  const v=rt.getGame().getVariables(); const club=v.get("ClubName").getAsString();
  const all=(globalThis.FB && Array.isArray(globalThis.FB.players))?globalThis.FB.players:[];
  const roster=all.filter(p=>p.owned && p.club===club).sort((a,b)=>a.name.localeCompare(b.name));
  let idx=Math.max(0,Math.min(roster.length-1,v.get("ContractSelectedIndex").getAsNumber()));
  v.get("ContractSelectedIndex").setNumber(idx);
  const p=roster[idx]; const wage=roster.reduce((s,x)=>s+(Number(x.salary)||0),0);
  const exp=roster.filter(x=>(Number(x.contractMonths)||0)<=6).length;
  v.get("ContractWageBill").setNumber(wage);v.get("ContractExpiringCount").setNumber(exp);v.get("ContractOwnedCount").setNumber(roster.length);
  v.get("ContractSelectedPlayerId").setNumber(p?p.id:-1);v.get("ContractSelectedName").setString(p?p.name:"No player selected");
  const sum=rt.getObjects("ContractSummary");if(sum.length)sum[0].setText("CLUB: "+club+" | PLAYERS: "+roster.length+" | TOTAL WAGE BILL: $"+Math.round(wage).toLocaleString("en-US")+" | CONTRACTS EXPIRING (6 MONTHS): "+exp+" | CLUB BUDGET: $"+Math.round(v.get("Budget").getAsNumber()).toLocaleString("en-US"));
  let detail="PLAYER CONTRACTS\n\n";
  if(p){detail+="Selected: "+p.name+" | "+p.pos+" | OVR "+p.ovr+"\n";detail+="Current wage: $"+Math.round(p.salary||0).toLocaleString("en-US")+"\n";detail+="Contract remaining: "+(p.contractMonths||((p.contract||1)*12))+" months\n";detail+="Estimated 12-month renewal bonus: $"+Math.round((p.salary||0)*2).toLocaleString("en-US")+"\n";detail+="Estimated 36-month renewal bonus: $"+Math.round((p.salary||0)*5).toLocaleString("en-US")+"\n";detail+="Next wage after negotiation: $"+Math.round((p.salary||0)*1.05).toLocaleString("en-US")+"\n\n";}
  roster.forEach((x,i)=>{detail+=(i+1)+". "+x.name+" | "+x.pos+" | OVR "+x.ovr+" | "+(x.contractMonths||((x.contract||1)*12))+" months\n";});
  const list=rt.getObjects("ContractPlayerText");if(list.length)list[0].setText(detail);
  const status=rt.getObjects("ContractStatusText");if(status.length)status[0].setText(v.get("ContractMessage").getAsString());
